css:
.nav-brand{display:flex;align-items:center;gap:14px}
.nav-brand .nav-sep{width:1px;height:28px;background:#d9dcea}
.nav-brand img.oreegami-logo{height:40px;width:auto;display:block}
.course-soon > a{cursor:default}
.course-soon .card-bestseller{background:#1b2140!important;color:#fff!important}
.course-soon .card-btn.card-btn-soon{background:#eef0fb!important;color:#764ba2!important;border:1px dashed #a9b2ea;box-shadow:none!important}
.course-soon .card-price{color:#764ba2;font-weight:600}
.catalog-group{font-size:13px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#6b7392;margin:36px 0 16px}
.catalog-top+.catalog-group{margin-top:8px}
.card-label{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;margin-bottom:8px}
.card-label-purple{color:#764ba2}.card-label-green{color:#0f9f6e}.card-label-blue{color:#4f63d6}
.card-desc{font-size:14px;line-height:1.55;color:#6b7392;margin:6px 0 12px}
.ctag-plain{background:#f3f4fa;color:#40465e;border:1px solid #e3e6f2;text-transform:none;letter-spacing:0;font-weight:600}
.course-card .card-thumb img{aspect-ratio:16/8;object-fit:cover;width:100%;height:auto}
.course-card .card-btn{background:linear-gradient(135deg,#667eea,#764ba2)!important;color:#fff!important}
.next-steps{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:44px}
.next-card{background:#fff;border:1px solid #e6e8f1;border-radius:16px;padding:26px 28px;box-shadow:0 6px 24px rgba(27,33,64,.05)}
.next-eyebrow{font-size:18px;font-weight:700;color:#1b2140;margin-bottom:8px}
.next-card p{color:#6b7392;font-size:15px;line-height:1.6;margin:0 0 18px}
.next-btn{display:inline-block;background:linear-gradient(135deg,#667eea,#764ba2);color:#fff!important;font-weight:700;font-size:14px;padding:12px 20px;border-radius:10px;text-decoration:none}
@media (max-width:760px){.next-steps{grid-template-columns:1fr}.nav-brand{gap:10px}.nav-brand img.oreegami-logo{height:30px}.nav-brand .nav-sep{height:22px}}

.course-card .card-thumb{height:auto!important;aspect-ratio:16/8;overflow:hidden}
.course-card .card-thumb img{height:100%!important;width:100%;object-fit:cover;aspect-ratio:auto}
.courses-grid.grid-flagship{grid-template-columns:1fr!important}
.grid-flagship .course-card > a{display:grid;grid-template-columns:1.15fr 1fr;align-items:stretch}
.grid-flagship .course-card .card-thumb{aspect-ratio:auto;min-height:100%}
.grid-flagship .card-info{display:flex;flex-direction:column;justify-content:center;padding:28px 30px}
.grid-flagship .card-title{font-size:22px}
@media (max-width:760px){.grid-flagship .course-card > a{display:block}.grid-flagship .course-card .card-thumb{aspect-ratio:16/8!important;min-height:0!important}}
